javascript.code:
function wait(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

async function main() {
  console.log('start')
  await wait(10)
  console.log('done')
}

main()
console.log('main returned')

typescript.code:
function wait(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

async function main(): Promise<void> {
  console.log('start')
  await wait(10)
  console.log('done')
}

main()
console.log('main returned')
